mapper.select:
SELECT r.id, r.name, r.description, r.file_url, r.external_link, r.resource_type, r.purchased_note, r.uploader_id, r.download_type, r.points_needed, r.created_at, r.updated_at, r.deleted_at, u.username as uploader_username FROM resources r LEFT JOIN users u ON r.uploader_id = u.id
r.deleted_at IS NULL
AND r.name LIKE CONCAT('%', #{name}, '%')
AND r.resource_type = #{resourceType}
AND r.download_type = #{downloadType}
ORDER BY r.created_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT r.id)
FROM resources r


        r.deleted_at IS NULL


        AND r.name LIKE CONCAT('%', #{name}, '%')


        AND r.resource_type = #{resourceType}


        AND r.download_type = #{downloadType}

